        // Given string S
        // Find the longest substring without duplicating characters.
        // s = bbbbbbb answer = b
        // s = abcbca answer = abc
        public static int LengthOfLongestSubstring(string s)
        {
            // dvdf
            // base cases
            if (s.Length == 1 || s.Length == 0)
                return s.Length;

            // dictionary of chars seen in current sub string
            // Also storing the index of what it was at so we can properly slide the sub window to the correct value. X + 1
            Dictionary<char, int> dict = new Dictionary<char, int>();
            int ws = 0; // window start

            int longestLength = 1;

            for (int i = 0; i < s.Length; i++)
            {
                if (dict.ContainsKey(s[i]))
                {
                    // HOLD ON JUST A SECOND
                    // If the index was previous to window start (ws) we can still increment the window!
                    dict.TryGetValue(s[i], out int value);

                    if (value < ws)
                    {
                        dict[s[i]] = i;
                        longestLength = (i + 1) - ws > longestLength ? (i + 1) - ws : longestLength;

                        continue;
                    }
                    else
                    {
                        // So when doing 'dvdf' for example
                        // when you hit that second d just go one OVER the first d it saw.
                        ws = dict[s[i]] + 1;

                        // Now update the index.
                        dict[s[i]] = i;

                        longestLength = (i + 1) - ws > longestLength ? (i + 1) - ws : longestLength;

                    }
                }
                else
                {
                    dict.Add(s[i], i);

                    longestLength = (i + 1) - ws > longestLength ? (i + 1) - ws : longestLength;
                }
            }
            return longestLength;
        }
    }
